#!/usr/bin/env node
/**
 * Generates MAP.md module maps (file → exports → local deps → rpc/tables) for src/**,
 * plus supabase/MAP.md (RPCs the app calls → args → latest migration).
 *
 *   node scripts/gen-maps.mjs           write all maps
 *   node scripts/gen-maps.mjs --check   exit 1 if any map is out of date (writes nothing)
 *
 * Output is deterministic (no timestamps). Never edit the generated files by hand.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.join(ROOT, 'src');
const CHECK = process.argv.includes('--check');
const MIN_FILES = 3;                       // a directory gets a MAP.md when it has >= this many source files
const SKIP_DIRS = new Set(['src/components/ui']); // shadcn primitives: not worth a map
const MAX_EXPORTS = 10;
const MAX_DEPS = 8;
const MAX_EXTRA = 8;
// frozen by the owner (AGENTS.md rule 3): listed, never described
const FROZEN = new Set(['src/pages/Warehouses.tsx', 'src/pages/StockTransfer.tsx', 'src/lib/cloud/warehouses-cloud.ts']);

// one-line responsibility per file (and per small folder / edge function). Source of truth: scripts/map-descriptions.json
const DESC_FILE = path.join(ROOT, 'scripts/map-descriptions.json');
const DESC = fs.existsSync(DESC_FILE) ? JSON.parse(fs.readFileSync(DESC_FILE, 'utf8')) : {};
const missing = new Set();   // keys that need a description
const used = new Set();      // description keys referenced by some map
const describe = (key) => {
  used.add(key);
  if (!DESC[key]) { missing.add(key); return '⚠ NO DESCRIPTION'; }
  return DESC[key];
};

const HEADER = (title, note) => `# MAP — ${title}
<!-- AUTO-GENERATED by scripts/gen-maps.mjs — do not edit by hand. Regenerate: npm run maps -->
${note}
`;

const rel = (p) => path.relative(ROOT, p).split(path.sep).join('/');
const isSource = (n) => /\.(ts|tsx)$/.test(n) && !/\.d\.ts$/.test(n) && !/\.(test|spec)\./.test(n);

function listDirs(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (!e.isDirectory() || e.name === '__tests__' || e.name === 'node_modules') continue;
    const full = path.join(dir, e.name);
    out.push(full);
    listDirs(full, out);
  }
  return out;
}
const sourceFiles = (dir) =>
  fs.readdirSync(dir, { withFileTypes: true }).filter((e) => e.isFile() && isSource(e.name)).map((e) => e.name).sort();

/** resolve an import specifier to a path relative to src (no extension), or null if not a local TS module */
function resolveLocal(fromFile, spec) {
  let base;
  if (spec.startsWith('@/')) base = path.join(SRC, spec.slice(2));
  else if (spec.startsWith('.')) base = path.resolve(path.dirname(fromFile), spec);
  else return null;
  for (const c of [base + '.ts', base + '.tsx']) if (fs.existsSync(c)) return rel(c).replace(/^src\//, '').replace(/\.tsx?$/, '');
  for (const c of [path.join(base, 'index.ts'), path.join(base, 'index.tsx')]) if (fs.existsSync(c)) return rel(path.dirname(c)).replace(/^src\//, '');
  return null;
}

const RPC_RE = /\.rpc\(\s*['"`]([a-zA-Z0-9_]+)['"`]/g;
const TABLE_RE = /\.from\(\s*['"`]([a-zA-Z0-9_]+)['"`]|(?:insertToSupabase|updateInSupabase|deleteFromSupabase|fetchFromSupabase|batchInsertToSupabase|upsertToSupabase|fetchIncrementalFromSupabase|hasCloudData)(?:<[^>]*>)?\(\s*['"`]([a-zA-Z0-9_]+)['"`]/g;

function analyze(file) {
  const text = fs.readFileSync(file, 'utf8');
  const kind = file.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, kind);
  const values = [], types = [];
  const staticDeps = new Set(), dynDeps = new Set();
  const has = (n, k) => n.modifiers?.some((m) => m.kind === k);
  const addDep = (set, spec) => { const r = resolveLocal(file, spec); if (r) set.add(r); };

  for (const st of sf.statements) {
    if (ts.isImportDeclaration(st)) {
      if (!st.importClause?.isTypeOnly) addDep(staticDeps, st.moduleSpecifier.text);
    } else if (ts.isExportDeclaration(st)) {
      const spec = st.moduleSpecifier?.text;
      if (spec && !st.isTypeOnly) addDep(staticDeps, spec);
      if (!st.exportClause) { if (spec) values.push(`*←${path.basename(spec)}`); }
      else if (ts.isNamedExports(st.exportClause)) {
        for (const el of st.exportClause.elements) (st.isTypeOnly || el.isTypeOnly ? types : values).push(el.name.text);
      }
    } else if (ts.isExportAssignment(st)) {
      values.push('default');
    } else if (has(st, ts.SyntaxKind.ExportKeyword)) {
      const isDefault = has(st, ts.SyntaxKind.DefaultKeyword);
      if (ts.isFunctionDeclaration(st) || ts.isClassDeclaration(st)) values.push(isDefault ? `default(${st.name?.text ?? ''})` : st.name?.text);
      else if (ts.isEnumDeclaration(st)) values.push(st.name.text);
      else if (ts.isInterfaceDeclaration(st) || ts.isTypeAliasDeclaration(st)) types.push(st.name.text);
      else if (ts.isVariableStatement(st)) {
        for (const d of st.declarationList.declarations) if (ts.isIdentifier(d.name)) values.push(d.name.text);
      }
    }
  }
  const walk = (n) => {
    if (ts.isCallExpression(n) && n.expression.kind === ts.SyntaxKind.ImportKeyword && n.arguments[0] && ts.isStringLiteralLike(n.arguments[0])) {
      addDep(dynDeps, n.arguments[0].text);
    }
    ts.forEachChild(n, walk);
  };
  walk(sf);

  const rpcs = new Set(), tables = new Set();
  for (const m of text.matchAll(RPC_RE)) rpcs.add(m[1]);
  for (const m of text.matchAll(TABLE_RE)) tables.add(m[1] || m[2]);
  return { values: values.filter(Boolean), types, staticDeps, dynDeps, rpcs, tables };
}

const cap = (arr, n) => (arr.length > n ? `${arr.slice(0, n).join(', ')} (+${arr.length - n})` : arr.join(', '));

function renderDeps(selfRel, a) {
  const stat = [...a.staticDeps], dyn = [...a.dynDeps].filter((d) => !a.staticDeps.has(d));
  let ui = false;
  const keep = (d) => {
    if (d === selfRel) return false;
    if (d.startsWith('components/ui/') || d === 'components/ui') { ui = true; return false; }
    return d !== 'lib/utils' && d !== 'integrations/supabase/client';
  };
  const selfDir = path.posix.dirname(selfRel);
  const short = (d) => (path.posix.dirname(d) === selfDir ? path.posix.basename(d) : d);
  const list = [...stat.filter(keep).sort().map(short), ...dyn.filter(keep).sort().map((d) => short(d) + '*')];
  if (ui) list.push('ui/*');
  return list.length ? cap(list, MAX_DEPS) : '—';
}

function renderDir(dir) {
  const dirRel = rel(dir);
  const files = sourceFiles(dir);
  files.forEach((f) => { if (FROZEN.has(rel(path.join(dir, f)))) used.add(rel(path.join(dir, f))); });
  const rows = files.map((f) => ({ f, a: analyze(path.join(dir, f)) }));
  const withExtra = rows.some((r) => r.a.rpcs.size || r.a.tables.size);
  const subs = fs.readdirSync(dir, { withFileTypes: true }).filter((e) => e.isDirectory() && e.name !== '__tests__')
    .map((e) => e.name).filter((n) => fs.existsSync(path.join(dir, n, 'MAP.md')) || mapDirs.has(rel(path.join(dir, n)))).sort();

  let out = HEADER(dirRel, `Role, exports and local dependencies only — no internals. ${files.length} files. Lists are capped; open the file for the rest.
\`dep*\` = dynamic import · bare name = same directory · \`ui/*\` = shadcn primitives · \`(+N)\` = more not shown.
Omitted as noise: \`integrations/supabase/client\`, \`lib/utils\`.${subs.length ? `\nSubfolders with their own map: ${subs.map((s) => s + '/').join(', ')}` : ''}
`);
  out += `\n| file | role | exports | local deps |${withExtra ? ' rpc · tables |' : ''}\n|---|---|---|---|${withExtra ? '---|' : ''}\n`;
  for (const { f, a } of rows) {
    if (FROZEN.has(rel(path.join(dir, f)))) {
      out += `| \`${f}\` | 🔒 FROZEN — do not read or edit | — | — |${withExtra ? ' — |' : ''}\n`;
      continue;
    }
    const selfRel = rel(path.join(dir, f)).replace(/^src\//, '').replace(/\.tsx?$/, '');
    let exp = a.values.length ? cap(a.values, MAX_EXPORTS) : (a.types.length ? 'types: ' + cap(a.types, MAX_EXPORTS) : '—');
    if (a.values.length && a.types.length) exp += ` · ${a.types.length} types`;
    let line = `| \`${f}\` | ${describe(rel(path.join(dir, f)))} | ${exp} | ${renderDeps(selfRel, a)} |`;
    if (withExtra) {
      const parts = [];
      if (a.rpcs.size) parts.push('rpc: ' + cap([...a.rpcs].sort(), MAX_EXTRA));
      if (a.tables.size) parts.push('tbl: ' + cap([...a.tables].sort(), MAX_EXTRA));
      line += ` ${parts.join(' · ') || '—'} |`;
    }
    out += line + '\n';
  }
  return out;
}

// ---- which directories get a map ----------------------------------------------------------------
const allDirs = [SRC, ...listDirs(SRC)];
const mapDirs = new Set(allDirs.filter((d) => rel(d) !== 'src' && !SKIP_DIRS.has(rel(d)) && sourceFiles(d).length >= MIN_FILES).map(rel));

// ---- src/MAP.md index ----------------------------------------------------------------------------
const PURPOSE = {
  'src/pages': 'one file per screen (route targets)',
  'src/hooks': 'React hooks (auth, currency, network, sync, device…)',
  'src/lib': 'domain logic: *-store.ts (local/offline state), money-engine, sync-queue, utilities',
  'src/lib/cloud': 'Supabase access per domain — every RPC call lives here',
  'src/lib/db': 'local database layer',
  'src/lib/locales': 'translation dictionaries',
  'src/lib/printer': 'receipt / A4 printing',
  'src/contexts': 'React contexts',
  'src/providers': 'app-wide providers (cloud sync…)',
  'src/types': 'shared TypeScript types',
  'src/integrations/supabase': 'Supabase client + generated types.ts (stale vs live DB)',
  'src/components/ui': 'shadcn/Radix primitives — import by name, do not read',
  'src/components/pos': 'POS screen pieces (cart, scanner dialogs, variants)',
  'src/components/settings': 'settings sections',
  'src/components/reports': 'reports tabs, charts, exports',
  'src/components/auth': 'login / signup / lock UI',
  'src/components/layout': 'main layout, headers, navigation',
  'src/components/license': 'license / subscription UI',
  'src/components/dashboard': 'dashboard widgets',
  'src/components/products': 'product & purchase forms',
  'src/components/purchases': 'purchase invoice views',
};
function renderIndex() {
  let out = HEADER('src (index)', `Read the MAP.md of the directory you need; do not open source files blindly. ${fs.readdirSync(SRC).length} entries at the root.\n`);
  out += '\n| directory | source files | purpose | map |\n|---|---|---|---|\n';
  for (const d of allDirs) {
    const r = rel(d);
    if (r === 'src') continue;
    const n = sourceFiles(d).length;
    if (!n && !PURPOSE[r] && !DESC[r + '/']) continue;
    if (DESC[r + '/']) used.add(r + '/');
    else if (n && !PURPOSE[r]) missing.add(r + '/');
    out += `| \`${r.replace(/^src\//, '')}/\` | ${n} | ${DESC[r + '/'] ?? PURPOSE[r] ?? '⚠ NO DESCRIPTION'} | ${mapDirs.has(r) ? `[MAP.md](${r.replace(/^src\//, '')}/MAP.md)` : '—'} |\n`;
  }
  return out;
}

// ---- supabase/MAP.md -----------------------------------------------------------------------------
function matchParen(s, open) {
  let depth = 0;
  for (let i = open; i < s.length; i++) {
    if (s[i] === '(') depth++;
    else if (s[i] === ')' && --depth === 0) return i;
  }
  return -1;
}
function splitTop(s) {
  const out = []; let depth = 0, cur = '';
  for (const ch of s) {
    if (ch === '(') depth++;
    if (ch === ')') depth--;
    if (ch === ',' && depth === 0) { out.push(cur); cur = ''; } else cur += ch;
  }
  if (cur.trim()) out.push(cur);
  return out;
}
function appRpcNames() {
  const names = new Set();
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const full = path.join(d, e.name);
      if (e.isDirectory()) walk(full);
      else if (/\.(ts|tsx)$/.test(e.name)) for (const m of fs.readFileSync(full, 'utf8').matchAll(RPC_RE)) names.add(m[1]);
    }
  };
  walk(SRC);
  return names;
}
// Real applied order on the live database (file names after 2026-11-20 do not always match it): scripts/migration-order.json
const MIGRATION_ORDER = JSON.parse(fs.readFileSync(path.join(ROOT, 'scripts/migration-order.json'), 'utf8')).applied_version_by_slug;
const effKey = (fileNoExt) => `${MIGRATION_ORDER[fileNoExt.replace(/^\d{14}_/, '')] ?? fileNoExt.slice(0, 14)}|${fileNoExt}`;

function renderSupabase() {
  const migDir = path.join(ROOT, 'supabase/migrations');
  const migs = fs.readdirSync(migDir).filter((f) => f.endsWith('.sql'))
    .sort((a, b) => effKey(a.replace(/\.sql$/, '')).localeCompare(effKey(b.replace(/\.sql$/, ''))));
  const sigs = new Map();          // name -> Map(argSig -> {args, file})
  const lastDrop = new Map();      // name -> file
  const CREATE = /CREATE\s+(?:OR\s+REPLACE\s+)?FUNCTION\s+(?:public\.)?"?([a-zA-Z0-9_]+)"?\s*\(/gi;
  const DROP = /DROP\s+FUNCTION\s+(?:IF\s+EXISTS\s+)?(?:public\.)?"?([a-zA-Z0-9_]+)"?/gi;
  for (const f of migs) {
    const text = fs.readFileSync(path.join(migDir, f), 'utf8');
    for (const m of text.matchAll(CREATE)) {
      const open = m.index + m[0].length - 1;
      const close = matchParen(text, open);
      if (close < 0) continue;
      const argText = text.slice(open + 1, close).replace(/\/\*[\s\S]*?\*\//g, '').replace(/--[^\n]*/g, '');
      const args = splitTop(argText).map((a) => {
        const t = a.trim().replace(/^(IN|OUT|INOUT|VARIADIC)\s+/i, '');
        const name = t.split(/\s+/)[0];
        return /\bDEFAULT\b|=/i.test(t) ? `${name}?` : name;
      }).filter(Boolean);
      const sig = args.join(', ');
      if (!sigs.has(m[1])) sigs.set(m[1], new Map());
      sigs.get(m[1]).set(sig, { args: sig, file: f.replace(/\.sql$/, ''), key: effKey(f.replace(/\.sql$/, '')) });
    }
    for (const m of text.matchAll(DROP)) lastDrop.set(m[1], effKey(f.replace(/\.sql$/, '')));
  }
  const app = appRpcNames();
  let out = HEADER('supabase', `Derived from the text of \`supabase/migrations/\` (${migs.length} files), NOT from the live database — verify against the live DB before trusting a signature.
Shows only the signature(s) defined by the NEWEST migration (by real applied order, scripts/migration-order.json) that defines each function. \`arg?\` = has a default.
\`older\` = distinct signatures in earlier migrations (may be replaced or still live as overloads). \`⚠ dropped later\` = a later migration drops this name.
`);
  const rows = [...app].sort();
  out += `\n## RPCs called by the app (${rows.length})\n\n| rpc | args | latest migration | older |\n|---|---|---|---|\n`;
  for (const n of rows) {
    if (!sigs.has(n)) { out += `| \`${n}\` | — | not found in migrations (live-only?) | — |\n`; continue; }
    const all = [...sigs.get(n).values()];
    const newest = all.map((x) => x.key).sort().pop();
    const current = all.filter((x) => x.key === newest);
    const older = all.length - current.length;
    const dropped = lastDrop.has(n) && lastDrop.get(n) > newest ? ' ⚠ dropped later' : '';
    for (const sgn of current) out += `| \`${n}\` | ${sgn.args || '—'} | ${sgn.file}${dropped} | ${older || '—'} |\n`;
  }
  const others = [...sigs.keys()].filter((n) => !app.has(n)).sort();
  out += `\n## Other SQL functions (${others.length}) — triggers / helpers, not called by the app\n\n${others.map((n) => '`' + n + '`').join(' · ')}\n`;
  out += `\n## Edge functions\n\nSee [functions/MAP.md](functions/MAP.md).\n`;
  return out;
}


// ---- maps for non-TypeScript folders: file | role (+ rpc · tables for edge functions) -----------------
const listFiles = (dir, re, recursive = false, skip = () => false) => {
  const out = [];
  const walk = (d) => {
    if (!fs.existsSync(d)) return;
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const full = path.join(d, e.name);
      if (skip(full)) continue;
      if (e.isDirectory()) { if (recursive && e.name !== 'node_modules') walk(full); }
      else if (re.test(e.name)) out.push(full);
    }
  };
  walk(dir);
  return out.sort();
};
function renderSimple(mapDir, title, note, entries, withExtra = false) {
  let out = HEADER(title, note);
  out += `\n| ${withExtra ? 'function' : 'file'} | role |${withExtra ? ' rpc · tables |' : ''}\n|---|---|${withExtra ? '---|' : ''}\n`;
  for (const e of entries) {
    const label = e.label ?? path.relative(mapDir, e.file).split(path.sep).join('/');
    let line = `| \`${label}\` | ${describe(e.key)} |`;
    if (withExtra) {
      const parts = [];
      if (e.rpcs?.size) parts.push('rpc: ' + cap([...e.rpcs].sort(), MAX_EXTRA));
      if (e.tables?.size) parts.push('tbl: ' + cap([...e.tables].sort(), MAX_EXTRA));
      line += ` ${parts.join(' · ') || '—'} |`;
    }
    out += line + '\n';
  }
  return out;
}
const fileEntries = (dir, files) => files.map((file) => ({ file, key: rel(file) }));
function renderSimpleMaps() {
  const m = new Map();
  const el = path.join(ROOT, 'electron');
  m.set(path.join(el, 'MAP.md'), renderSimple(el, 'electron', 'Windows desktop shell (Electron). Role per file.\n',
    fileEntries(el, listFiles(el, /\.(js|html)$/))));
  const sc = path.join(ROOT, 'scripts');
  m.set(path.join(sc, 'MAP.md'), renderSimple(sc, 'scripts', 'Build, release, maintenance and test scripts. Role per file.\n',
    fileEntries(sc, listFiles(sc, /\.(mjs|js|cjs|ps1)$/, true))));
  const an = path.join(ROOT, 'android/app/src');
  m.set(path.join(an, 'MAP.md'), renderSimple(an, 'android/app/src', 'Custom native Android code (Capacitor plugins). Default example tests omitted.\n',
    fileEntries(an, listFiles(path.join(an, 'main/java'), /\.(java|kt)$/, true))));
  const wf = path.join(ROOT, '.github/workflows');
  m.set(path.join(wf, 'MAP.md'), renderSimple(wf, '.github/workflows', 'CI workflows. Role per file.\n',
    fileEntries(wf, listFiles(wf, /\.ya?ml$/))));
  const fn = path.join(ROOT, 'supabase/functions');
  const fnEntries = fs.readdirSync(fn, { withFileTypes: true }).filter((e) => e.isDirectory() && !e.name.startsWith('_')).map((e) => {
    const dir = path.join(fn, e.name);
    const text = listFiles(dir, /\.(ts|js)$/, true).map((f) => fs.readFileSync(f, 'utf8')).join('\n');
    const rpcs = new Set(), tables = new Set();
    for (const x of text.matchAll(RPC_RE)) rpcs.add(x[1]);
    for (const x of text.matchAll(TABLE_RE)) tables.add(x[1] || x[2]);
    return { label: e.name + '/', key: `supabase/functions/${e.name}/`, rpcs, tables };
  }).sort((a, b) => a.label.localeCompare(b.label));
  m.set(path.join(fn, 'MAP.md'), renderSimple(fn, 'supabase/functions', `Edge functions (Deno). ${fnEntries.length} functions; shared code lives in \`_shared/\`.\n`, fnEntries, true));
  return m;
}

// ---- write / check -------------------------------------------------------------------------------
const outputs = new Map();
outputs.set(path.join(SRC, 'MAP.md'), renderIndex());
for (const r of [...mapDirs].sort()) outputs.set(path.join(ROOT, r, 'MAP.md'), renderDir(path.join(ROOT, r)));
outputs.set(path.join(ROOT, 'supabase/MAP.md'), renderSupabase());
for (const [f, c] of renderSimpleMaps()) outputs.set(f, c);

// descriptions integrity: missing and orphan entries both fail --check
const orphans = Object.keys(DESC).filter((k) => !used.has(k) && !fs.existsSync(path.join(ROOT, k)));
const unused = Object.keys(DESC).filter((k) => !used.has(k) && fs.existsSync(path.join(ROOT, k)));
let problems = 0;
if (missing.size) { problems++; console.error(`missing description (add to scripts/map-descriptions.json):\n  ${[...missing].sort().join('\n  ')}`); }
if (orphans.length) { problems++; console.error(`orphan description (file/folder no longer exists — remove):\n  ${orphans.sort().join('\n  ')}`); }
if (unused.length && CHECK) console.error(`note: ${unused.length} description(s) not shown in any map (harmless)`);

let stale = 0;
for (const [file, content] of outputs) {
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === content) continue;
  stale++;
  if (CHECK) console.error(`out of date: ${rel(file)}`);
  else { fs.writeFileSync(file, content); console.log(`wrote ${rel(file)}`); }
}
if (CHECK) {
  if (stale) { console.error(`${stale} map(s) out of date — run: npm run maps`); process.exit(1); }
  if (problems) process.exit(1);
  console.log(`all ${outputs.size} maps up to date`);
} else {
  console.log(`${outputs.size} maps generated (${stale} changed)`);
  if (problems) process.exit(1);
}
